import { Subflow, FlowObject, FlowArray, action, wfa } from '@servicenow/sdk/automation'
import { StringColumn, BooleanColumn, IntegerColumn, DateTimeColumn, ReferenceColumn } from '@servicenow/sdk/core'

/**
 * Data Processing Subflow with comprehensive input types
 * Demonstrates: integer, string, datetime, choice, object, array inputs
 */
export const dataProcessingSubflow = Subflow(
    {
        $id: Now.ID['data_processing_subflow'],
        name: 'Data Processing Subflow',
        description:
            'Processes data with various input types including integer, string, datetime, choice, object, and array',
        runAs: 'system',
        inputs: {
            // Integer input - priority level
            priority: IntegerColumn({
                label: 'Priority Level',
                mandatory: true,
                hint: 'Priority level from 1-5 where 1 is highest',
            }),
            // String input - description text
            description: StringColumn({
                label: 'Description',
                mandatory: true,
                maxLength: 500,
                hint: 'Detailed description of the data to process',
            }),
            // DateTime input - due date
            dueDate: DateTimeColumn({
                label: 'Due Date',
                mandatory: true,
                hint: 'Date and time when processing should be completed',
            }),
            // Choice input - processing category (represented as string with validation)
            category: StringColumn({
                label: 'Processing Category',
                mandatory: true,
                hint: 'Category: urgent, normal, low, maintenance',
            }),
            // Object input - complex configuration data
            configuration: FlowObject({
                label: 'Configuration Object',
                fields: {
                    environment: StringColumn({
                        label: 'Environment',
                        mandatory: true,
                    }),
                    batchSize: IntegerColumn({
                        label: 'Batch Size',
                        mandatory: true,
                    }),
                    enableLogging: BooleanColumn({
                        label: 'Enable Logging',
                        mandatory: true,
                    }),
                    settings: FlowObject({
                        label: 'Nested Settings',
                        fields: {
                            retryCount: IntegerColumn({
                                label: 'Retry Count',
                                mandatory: false,
                            }),
                            timeout: IntegerColumn({
                                label: 'Timeout (seconds)',
                                mandatory: false,
                            }),
                        },
                    }),
                },
            }),
            // Array input - list of items to process
            items: FlowArray({
                label: 'Items to Process',
                elementType: FlowObject({
                    label: 'Processing Item',
                    fields: {
                        id: StringColumn({
                            label: 'Item ID',
                            mandatory: true,
                        }),
                        name: StringColumn({
                            label: 'Item Name',
                            mandatory: true,
                        }),
                        value: IntegerColumn({
                            label: 'Item Value',
                            mandatory: false,
                        }),
                        active: BooleanColumn({
                            label: 'Is Active',
                            mandatory: true,
                        }),
                    },
                }),
                childName: 'ProcessingItem',
            }),
            // Reference input - assigned user
            assignedTo: ReferenceColumn({
                label: 'Assigned To',
                mandatory: false,
                referenceTable: 'sys_user',
                hint: 'User assigned to oversee the processing',
            }),
        },
        outputs: {
            success: BooleanColumn({
                label: 'Processing Successful',
                mandatory: true,
            }),
            processedCount: IntegerColumn({
                label: 'Items Processed Count',
                mandatory: true,
            }),
            resultMessage: StringColumn({
                label: 'Result Message',
                mandatory: true,
            }),
        },
    },
    (_params) => {
        // Log the start of processing
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_processing_start'],
                annotation: 'Log the start of data processing',
            },
            {
                log_level: 'info',
                log_message: `Starting data processing with priority ${wfa.dataPill(_params.inputs.priority, 'integer')} and category ${wfa.dataPill(_params.inputs.category, 'string')}`,
            }
        )
        // Process items based on configuration
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.inputs.items, 'array.object'),
            {
                $id: Now.ID['process_items'],
                annotation: 'Process each item in the array',
            },
            (item) => {
                // Only process active items
                wfa.flowLogic.if(
                    {
                        $id: Now.ID['check_active'],
                        condition: `${wfa.dataPill(item.active, 'boolean')}=true`,
                        annotation: 'Check if item is active',
                    },
                    () => {
                        // Log processing of each active item
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_item_processing'],
                                annotation: 'Log processing of individual item',
                            },
                            {
                                log_level: 'info',
                                log_message: `Processing item: ${wfa.dataPill(item.name, 'string')} with ID: ${wfa.dataPill(item.id, 'string')}`,
                            }
                        )
                    }
                )
            }
        )
        // Check priority level and take appropriate action
        wfa.flowLogic.if(
            {
                $id: Now.ID['check_urgent_priority'],
                condition: `${wfa.dataPill(_params.inputs.priority, 'integer')}=1`,
                annotation: 'Check if priority is urgent (1)',
            },
            () => {
                // Log urgent priority instead of sending email (to avoid reference field access)
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_urgent'],
                        annotation: 'Log urgent priority processing',
                    },
                    {
                        log_level: 'warn',
                        log_message: `Urgent data processing started for: ${wfa.dataPill(_params.inputs.description, 'string')}. Due date: ${wfa.dataPill(_params.inputs.dueDate, 'string')}.`,
                    }
                )
            }
        )
        wfa.flowLogic.elseIf(
            {
                $id: Now.ID['check_high_priority'],
                condition: `${wfa.dataPill(_params.inputs.priority, 'integer')}=2`,
                annotation: 'Check if priority is high (2)',
            },
            () => {
                // Log high priority processing
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_high_priority'],
                        annotation: 'Log high priority processing',
                    },
                    {
                        log_level: 'warn',
                        log_message: `High priority data processing in progress: ${wfa.dataPill(_params.inputs.description, 'string')}`,
                    }
                )
            }
        )
        // Set processing results as outputs
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign_outputs'],
                annotation: 'Assign processing results to subflow outputs',
            },
            _params.outputs,
            {
                success: true,
                processedCount: 5,
                resultMessage: `Successfully processed data for category: ${wfa.dataPill(_params.inputs.category, 'string')}`,
            }
        )
    }
)
